from __future__ import annotations
from typing import Sequence

def validate_rank_trace(ranks: Sequence[int], capacity: int) -> bool:
    """Test boundedness and monotonicity of a finite quality trace."""
    if not ranks or capacity < 0:
        return False
    return all(0 <= x <= capacity for x in ranks) and all(
        a <= b for a, b in zip(ranks, ranks[1:])
    )

if __name__ == "__main__":
    print(validate_rank_trace([1, 3, 4, 7, 8, 8], 8))

from __future__ import annotations
from dataclasses import dataclass
from typing import Callable

@dataclass(frozen=True)
class State:
    quality: int

def bounded_run(initial: State, capacity: int,
                choose_gain: Callable[[State, int], int], steps: int) -> list[State]:
    """Generate a run whose outcome range depends on remaining capacity."""
    result = [initial]
    for _ in range(steps):
        current = result[-1]
        gain = choose_gain(current, capacity)
        if not 0 <= gain <= capacity - current.quality:
            raise ValueError("inadmissible state-dependent outcome")
        result.append(State(current.quality + gain))
    return result

if __name__ == "__main__":
    run = bounded_run(State(0), 6, lambda s, k: min(2, k-s.quality), 6)
    print([s.quality for s in run])

